export async function listAllLiveIssues(
  orgId: OrgId,
  projectId: ProjectId,
): Promise<readonly Issue[]> {
  const rows = getDb()
    .select()
    .from(issues)
    .where(
      and(
        ...compact(
          orgPredicate(issues.orgId, orgId),
          eq(issues.projectId, projectId),
          livePredicate(issues.archivedAt, {}),
        ),
      ),
    )
    .orderBy(issues.number)
    .all();

  const labels = await listLabelsForIssues(
    orgId,
    rows.map((row) => row.id as IssueId),
  );
  return rows.map((row) =>
    toIssue(row, (labels[row.id] ?? []).map((label) => label.id)),
  );
}

/**
 * Inserts fresh copies of `sources` into `toProjectId` for a project clone:
 * content and labels are kept, progress is reset, numbering restarts at 1.
 */
export async function insertIssueCopies(
  orgId: OrgId,
  toProjectId: ProjectId,
  sources: readonly Issue[],
  authorId: UserId,
  status: IssueStatus,
): Promise<number> {
  const db = getDb();
  const stamp = toIsoTimestamp(new Date());

  sources.forEach((issue, index) => {
    const id = newId();
    db.insert(issues)
      .values({
        id,
        orgId,
        projectId: toProjectId,
        number: index + 1,
        title: issue.title,
        description: issue.description,
        status,
        priority: issue.priority,
        authorId,
        assigneeId: null,
        parentId: null,
        estimate: issue.estimate,
        dueAt: issue.dueAt,
        startedAt: null,
        completedAt: null,
        createdAt: stamp,
        updatedAt: stamp,
      })
      .run();

    if (issue.labelIds.length > 0) {
      db.insert(issueLabels)
        .values(
          issue.labelIds.map((labelId) => ({ orgId, issueId: id, labelId })),
        )
        .run();
    }
  });

  return sources.length;
}

